//! Trail 394 spike: oxc vs tsrs parse/bind cost, and oxc_resolver (caliper's config) vs tsrs_module resolution.
//! Usage: tsrs-spike <mode> <root> [reps]
//!   modes: parse-oxc | parse-tsrs | parse-tsrs-bind | resolve-oxc | resolve-tsrs | resolve-compare
//!   <root> holds tsconfig.json and src/; parse modes also take extra dirs via SPIKE_EXTRA (colon separated).

use std::path::{Path, PathBuf};
use std::time::Instant;

use oxc_allocator::Allocator;
use oxc_ast::ast::{ModuleDeclaration, Statement};
use oxc_parser::Parser;
use oxc_resolver::{ResolveOptions, Resolver, TsconfigDiscovery};
use oxc_span::SourceType;

fn walk(dir: &Path, out: &mut Vec<PathBuf>) {
    let Ok(rd) = std::fs::read_dir(dir) else { return };
    for e in rd.flatten() {
        let p = e.path();
        if p.is_dir() {
            walk(&p, out);
        } else if let Some(n) = p.to_str() {
            if n.ends_with(".ts") || n.ends_with(".tsx") || n.ends_with(".mts") || n.ends_with(".cts") {
                out.push(p);
            }
        }
    }
}

fn files(root: &Path, extra: bool) -> Vec<(PathBuf, String)> {
    let mut v = Vec::new();
    walk(&root.join("src"), &mut v);
    if extra {
        if let Ok(x) = std::env::var("SPIKE_EXTRA") {
            for d in x.split(':') {
                walk(Path::new(d), &mut v);
            }
        }
    }
    v.sort();
    v.into_iter().map(|p| { let s = std::fs::read_to_string(&p).unwrap_or_default(); (p, s) }).collect()
}

fn specifiers(path: &Path, src: &str) -> Vec<String> {
    let alloc = Allocator::default();
    let st = SourceType::from_path(path).unwrap_or_default();
    let ret = Parser::new(&alloc, src, st).parse();
    let mut out = Vec::new();
    for s in &ret.program.body {
        if let Some(m) = s.as_module_declaration() {
            let spec = match m {
                ModuleDeclaration::ImportDeclaration(d) => d.source.value.as_str().map(str::to_owned),
                ModuleDeclaration::ExportAllDeclaration(d) => d.source.value.as_str().map(str::to_owned),
                ModuleDeclaration::ExportFromDeclaration(d) => d.source.value.as_str().map(str::to_owned),
                _ => None,
            };
            out.extend(spec);
        }
        let _ = matches!(s, Statement::EmptyStatement(_));
    }
    out
}

/// caliper's `resolve_options` (crates/core/src/resolver/mod.rs:710-736), no custom conditions.
fn oxc_resolvers() -> (Resolver, Resolver) {
    let aliases = |js: &str, ts: &[&str]| (js.to_owned(), ts.iter().map(|e| (*e).to_owned()).collect());
    let main = ResolveOptions {
        condition_names: ["types", "import", "require", "default"].map(String::from).to_vec(),
        main_fields: vec!["types".into(), "typings".into(), "module".into(), "main".into()],
        extensions: [".ts", ".tsx", ".d.ts", ".d.mts", ".d.cts", ".js"].map(String::from).to_vec(),
        extension_alias: vec![
            aliases(".js", &[".ts", ".tsx", ".d.ts", ".js"]),
            aliases(".jsx", &[".tsx", ".jsx"]),
            aliases(".mjs", &[".mts", ".d.mts", ".mjs"]),
            aliases(".cjs", &[".cts", ".d.cts", ".cjs"]),
        ],
        tsconfig: Some(TsconfigDiscovery::Auto),
        ..ResolveOptions::default()
    };
    let tf = ResolveOptions { condition_names: vec!["types".into()], ..main.clone() };
    (Resolver::new(main), Resolver::new(tf))
}

/// caliper's `resolve_module_with` + `resolve_package_types_file` (resolver/import.rs:288-318, react.rs:115-131).
fn oxc_resolve(main: &Resolver, tf: &Resolver, spec: &str, from: &Path) -> Option<String> {
    if !spec.starts_with('.') && !spec.starts_with('/') {
        let decl = |r: &Resolver, s: &str| {
            let res = r.resolve_dts(from, s).ok()?;
            let p = res.path().to_string_lossy().into_owned();
            ([".d.ts", ".d.mts", ".d.cts"].iter().any(|e| p.ends_with(e)) && res.path().is_file()).then_some(p)
        };
        let mangled = spec.strip_prefix('@').map_or_else(|| spec.to_owned(), |r| r.replacen('/', "__", 1));
        if let Some(p) = decl(main, spec).or_else(|| decl(tf, spec)).or_else(|| decl(main, &format!("@types/{mangled}"))) {
            return Some(p);
        }
    }
    main.resolve_file(from, spec).ok().map(|r| r.path().to_string_lossy().into_owned())
}

