    pub fn resolve(r: &tsrs_module::DefaultResolver<'_>, spec: &str, from: &Path) -> Option<String> {
        let (m, _) = r.resolve_module_name(spec, from.to_str()?, ModuleKind::ES_NEXT, None).ok()?;
