            file_name: name,
            external_module_indicator_options: Default::default(),
        };
        let file = tsrs_parser::parse_source_file(opts, src, kind);
        if bind {
            tsrs_binder::bind_source_file(file);
        }
        file.statements.nodes().len()
    }
}

